// Share preparation stays local; users complete posting in their chosen app.
const shareDialog=document.createElement('dialog');shareDialog.id='share-dialog';shareDialog.setAttribute('aria-labelledby','share-heading');shareDialog.innerHTML=`<div class="dialog-head"><span>PASS THE CURIOSITY</span><button id="close-share" aria-label="Close share dialog">✕</button></div><h2 id="share-heading">Pass this Slice along.</h2><div class="share-summary"><span>✳</span><div><strong id="share-title"></strong><small id="share-author"></small></div></div><div class="share-platforms" aria-label="Share platforms"><button data-platform="wechat"><b class="wechat">W</b>WeChat / Moments</button><button data-platform="red"><b class="red">RedNote</b>RedNote</button><button data-platform="qq"><b class="qq">QQ</b>QQ</button><button data-platform="weibo"><b class="weibo">W</b>Weibo</button></div><div class="share-guide"><strong id="share-guide-title">Choose a platform to share</strong><p id="share-guide-text">Send the link to a friend or copy the caption to your favorite app.</p></div><label class="share-label">Share caption<textarea id="share-copy" rows="5"></textarea></label><div class="share-actions"><button id="copy-share-text">Copy caption</button><button id="copy-share-link">Copy link</button><button id="native-share" class="dark">More / Share via device ↗</button></div><p id="share-feedback" role="status" aria-live="polite"></p><p class="share-footnote">These options provide sharing instructions. You choose when to send or post. Available sharing apps depend on your device.</p>`;document.body.append(shareDialog);
let sharedWork=null,sharedURL='';
const shareGuides={wechat:['WeChat / Moments','Copy the link and paste it into a WeChat chat. For Moments, copy the caption and add a screenshot, or try your device sharing menu.'],red:['Share to RedNote','Copy the caption into a new RedNote post and add a screenshot or recording. Link support depends on the platform.'],qq:['Share to QQ','Copy the link and paste it into a QQ chat, or use your device sharing menu.'],weibo:['Share to Weibo','Paste the caption into a new Weibo post, add a screenshot if you like, then review and post.']};
function openSliceShare(id){const w=works.find(x=>x.id===id);if(!w)return;sharedWork=w;const url=new URL(location.pathname,location.origin);url.hash='work='+encodeURIComponent(w.id);sharedURL=w.local?'':url.href;document.querySelector('#share-title').textContent=w.title;document.querySelector('#share-author').textContent=w.author+' · '+w.cat;document.querySelector('#share-copy').value=`${w.title}\n\n${w.desc}\n\nFrom ${w.author} on Slice${sharedURL?'\nTry it: '+sharedURL:'\n(Local creation, not yet public)'}\n#Slice #InteractiveExperiences`;document.querySelector('#copy-share-link').disabled=!sharedURL;document.querySelector('#native-share').disabled=!navigator.share;document.querySelector('#share-guide-title').textContent=w.local?'This Slice is saved locally only':'Choose a platform to share';document.querySelector('#share-guide-text').textContent=w.local?'You can copy the caption, but there is no public link yet.':'Send the link to a friend or copy the caption to your favorite app.';document.querySelector('#share-feedback').textContent=navigator.share?'':'Device sharing is unavailable in this browser. Copy the caption or link instead.';shareDialog.querySelectorAll('[data-platform]').forEach(b=>b.setAttribute('aria-pressed','false'));shareDialog.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-share]');if(b){e.preventDefault();e.stopImmediatePropagation();openSliceShare(b.dataset.share)}},true);
shareDialog.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{shareDialog.querySelectorAll('[data-platform]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const guide=shareGuides[b.dataset.platform];document.querySelector('#share-guide-title').textContent=guide[0];document.querySelector('#share-guide-text').textContent=guide[1]+(sharedURL?'':' This Slice has no public link yet. You can share its caption.')});
async function copySliceShare(linkOnly){const field=document.querySelector('#share-copy'),value=linkOnly?sharedURL:field.value;if(!value)return;try{await navigator.clipboard.writeText(value);document.querySelector('#share-feedback').textContent=(linkOnly?'Link':'Caption')+' copied. Paste it into your chosen app.'}catch{field.value=value;field.focus();field.select();document.querySelector('#share-feedback').textContent='Copy permission was denied. The text is selected for manual copying.'}}
document.querySelector('#copy-share-text').onclick=()=>copySliceShare(false);document.querySelector('#copy-share-link').onclick=()=>copySliceShare(true);document.querySelector('#native-share').onclick=async()=>{try{await navigator.share({title:sharedWork.title,text:document.querySelector('#share-copy').value});document.querySelector('#share-feedback').textContent='Opened device sharing.'}catch(e){document.querySelector('#share-feedback').textContent=e.name==='AbortError'?'Sharing canceled.':'Device sharing is unavailable. Copy the caption or link.'}};document.querySelector('#close-share').onclick=()=>shareDialog.close();shareDialog.addEventListener('click',e=>{if(e.target===shareDialog){const r=shareDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)shareDialog.close()}});
const detailShare=document.createElement('button');detailShare.textContent='↗ Share';detailShare.onclick=()=>openSliceShare(activeId);document.querySelector('.dialog-bottom').prepend(detailShare);
